import{_ as e,c as i,o,ag as s}from"./chunks/framework.DfL_BkQ-.js";const m=JSON.parse('{"title":"Política de privacidad","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/privacy.md","filePath":"es/guide/privacy.md","lastUpdated":1794112334000}'),r={name:"es/guide/privacy.md"};function n(c,a,t,l,d,p){return o(),i("div",null,[...a[0]||(a[0]=[s('<h1 id="politica-de-privacidad" tabindex="-1">Política de privacidad <a class="header-anchor" href="#politica-de-privacidad" aria-label="Permalink to &quot;Política de privacidad&quot;">​</a></h1><h2 id="recopilacion-de-datos" tabindex="-1">Recopilación de datos <a class="header-anchor" href="#recopilacion-de-datos" aria-label="Permalink to &quot;Recopilación de datos&quot;">​</a></h2><p>El desarrollador no recopila ningún dato de esta aplicación.</p><h3 id="informacion-que-no-recopilamos" tabindex="-1">Información que no recopilamos <a class="header-anchor" href="#informacion-que-no-recopilamos" aria-label="Permalink to &quot;Información que no recopilamos&quot;">​</a></h3><ul><li>Información personal</li><li>Estadísticas de uso</li><li>Información del dispositivo</li><li>Datos de ubicación</li><li>Contenido o metadatos de imágenes</li><li>Historial de navegación</li><li>Cualquier otro dato del usuario</li></ul><h3 id="extension-de-chrome" tabindex="-1">Extensión de Chrome <a class="header-anchor" href="#extension-de-chrome" aria-label="Permalink to &quot;Extensión de Chrome&quot;">​</a></h3><p>La extensión de Chrome de Nicasa solicita acceso al contenido de la página únicamente para extraer las URL de las imágenes con fines de visualización. La extensión:</p><ul><li>No lee ni almacena el historial de navegación</li><li>No rastrea el comportamiento del usuario</li><li>No transmite ningún dato a servidores externos</li><li>Solo procesa las URL de las imágenes localmente en tu navegador</li></ul><h3 id="procesamiento-local" tabindex="-1">Procesamiento local <a class="header-anchor" href="#procesamiento-local" aria-label="Permalink to &quot;Procesamiento local&quot;">​</a></h3><p>Todo el procesamiento, la edición y la visualización de imágenes ocurren localmente en tu dispositivo. No se sube ninguna imagen ni dato a servidores externos.</p><h3 id="permisos" tabindex="-1">Permisos <a class="header-anchor" href="#permisos" aria-label="Permalink to &quot;Permisos&quot;">​</a></h3><p>Nicasa solicita los siguientes permisos en macOS:</p><ul><li><strong>Grabación de pantalla</strong>: necesaria para la función de captura</li><li><strong>Accesibilidad</strong>: opcional, se usa para las funciones del modo superposición</li><li><strong>Archivos y carpetas</strong>: acceso a los directorios elegidos por el usuario para navegar por imágenes</li></ul><p>Estos permisos se pueden gestionar en Ajustes del Sistema &gt; Privacidad y seguridad.</p><h3 id="servicios-de-terceros" tabindex="-1">Servicios de terceros <a class="header-anchor" href="#servicios-de-terceros" aria-label="Permalink to &quot;Servicios de terceros&quot;">​</a></h3><p>Nicasa no se integra con ningún servicio de análisis, publicidad o recopilación de datos de terceros.</p><h3 id="opciones-de-privacidad" tabindex="-1">Opciones de privacidad <a class="header-anchor" href="#opciones-de-privacidad" aria-label="Permalink to &quot;Opciones de privacidad&quot;">​</a></h3><p>Si deseas ejercer tus derechos de privacidad (por ejemplo: solicitudes de acceso, eliminación, portabilidad u oposición), o si crees que Nicasa tiene datos personales sobre ti, puedes enviar una solicitud mediante uno de los métodos siguientes:</p><ul><li>Correo electrónico: <a href="mailto:nicasa@w3cub.com" target="_blank" rel="noreferrer">nicasa@w3cub.com</a></li><li>Abrir una incidencia de privacidad: <a href="https://github.com/nicasa-app/nicasa-support/issues" target="_blank" rel="noreferrer">https://github.com/nicasa-app/nicasa-support/issues</a></li><li>Usar nuestra página de Opciones de privacidad: /es/guide/privacy-choices</li></ul><p>Dado que Nicasa no recopila datos personales como se describe arriba, muchas solicitudes se responderán confirmando que no se dispone de datos personales. Si en futuras versiones comenzamos a recopilar datos personales, esta página y el formulario de Opciones de privacidad ofrecerán una forma de enviar y hacer seguimiento de las solicitudes.</p><p>Nuestro objetivo es responder a las solicitudes de privacidad legítimas en un plazo de 30 días.</p><h3 id="actualizaciones" tabindex="-1">Actualizaciones <a class="header-anchor" href="#actualizaciones" aria-label="Permalink to &quot;Actualizaciones&quot;">​</a></h3><p>Esta política de privacidad puede actualizarse con nuevas versiones de la aplicación. Se notificará a los usuarios cualquier cambio significativo.</p><h3 id="contacto" tabindex="-1">Contacto <a class="header-anchor" href="#contacto" aria-label="Permalink to &quot;Contacto&quot;">​</a></h3><p>Para cuestiones relacionadas con la privacidad, contáctanos a través del <a href="https://github.com/nicasa-app/nicasa-support/issues" target="_blank" rel="noreferrer">repositorio de GitHub</a>.</p>',25)])])}const h=e(r,[["render",n]]);export{m as __pageData,h as default};
